use polymorfa_sdk::{MessagingClient, ClientOptions, Credential};

#[tokio::main(flavor = "current_thread")]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let sdk = MessagingClient::new(Credential::organization_api_key("{{POLYMORFA_API_KEY}}")?, ClientOptions::default())?;
    let result = sdk.messages().set_typing("{{session}}", &polymorfa_sdk::models::TypingRequest { conversation: polymorfa_sdk::models::ConversationReference::id("42"), id: None, state: polymorfa_sdk::models::TypingState::Paused }, Default::default()).await?;
    println!("{:?}", result);
    Ok(())
}

