import (
  "context"
  "fmt"
  "log"
  sdk "github.com/polymorfa/sdks/packages/go"
)

func main() {
  ctx := context.Background()
  api, err := sdk.NewMessagingClient(sdk.Config{Credential: sdk.Credential{Kind: sdk.OrganizationAPIKey, Value: "{{POLYMORFA_API_KEY}}"}})
  if err != nil { log.Fatal(err) }
  result, err := api.Messages().Star(ctx, "{{session}}", sdk.StarRequest{Conversation: sdk.ConversationReference{ID: "42"}, ID: "43", Star: false})
  if err != nil { log.Fatal(err) }
  fmt.Println(result)
}

